58	/**
59	 * City + ISO country for an IP from the bundled geoip-lite dataset, or null when
60	 * unresolvable. This is the client-profile fallback: when a customer has an IP on
61	 * record but none of their Visit rows were geocoded by the background job yet, we
62	 * still show *a* location rather than "unknown". Same private/loopback guard as
63	 * `countryFromIp`. Node runtime only.
64	 */
65	export function geoLocateIp(ip: string | null | undefined): IpLocation | null {
66	  if (!ip) return null;
67	  if (
68	    ip === "127.0.0.1" ||
69	    ip === "::1" ||
70	    ip.startsWith("10.") ||
71	    ip.startsWith("192.168.") ||
72	    /^172\.(1[6-9]|2\d|3[01])\./.test(ip)
73	  ) {
74	    return null;
75	  }
76	  try {
77	    const hit = geoip.lookup(ip);
78	    if (!hit) return null;
79	    const cc = hit.country?.trim().toUpperCase() || null;
80	    const country = cc && cc.length === 2 ? cc : null;
81	    const city = hit.city?.trim() || null;
82	    if (!country && !city) return null;
83	    return { country, city };
84	  } catch {
85	    return null;
86	  }
87	}
