89	  // — revalidate the whole subtree, or a client-side nav to a route Next has
90	  // already cached (from before this write) can render the layout without
91	  // ever re-checking the field, and the prompt reappears despite the DB
92	  // already being correct.
93	  revalidatePath("/dashboard", "layout");
94	  return { ok: true };
95	}
