345	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
346	  //
347	  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
348	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
349	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
350	  // client sent — so the leftmost entry is a free-text field the caller filled
351	  // in, and keying on it meant an attacker could rotate one header value per
352	  // request and never bind this limiter at all. That is the limiter standing
353	  // between a known email address and unlimited password guesses, and (below)
354	  // unlimited 2FA code guesses once a password is known. See the docblock on
355	  // `clientIp` for the measurement.
356	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
357	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
358	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
359	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
360	
361	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
362	  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
363	  //
364	  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
365	  // never ran. The reply text was correctly identical either way, but the reply
366	  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
367	  // gap one sample per address is enough to read. That turns the login form into
368	  // an account-enumeration oracle: "does this person bank here", answered for any
369	  // address, at scale, without ever guessing a password.
370	  //
371	  // It was materially worse while the throttle above was keyed on the
372	  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
373	  // would otherwise cap sampling could itself be stepped around per request. That
374	  // is fixed, but a defence that only works because another defence works is not
375	  // one, so the timing is equalised on its own terms.
376	  //
377	  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
378	  // same ~250ms. Keep the reply string identical to the wrong-password case.
379	  const passwordOk = user
380	    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
381	    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
382	  // `!user` is repeated here purely so TypeScript narrows `user` for the code
383	  // below. It is NOT a short-circuit any more: `passwordOk` above has already
384	  // spent the bcrypt comparison in both branches, which is the whole point.
385	  if (!user || !passwordOk) {
386	    return { error: "Invalid email or password." };
387	  }
388	  if (user.suspended) return { error: "This account is suspended." };
389	
390	  // Two-factor challenge, if enabled on the account.
391	  if (user.totpEnabled) {
392	    const code = String(formData.get("code") ?? "").trim();
393	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
394	    if (!(await verifyTotpForUser(user.id, code))) {
395	      return { error: "Invalid 2FA code.", needs2fa: true };
396	    }
397	  }
398	
399	  resetRateLimit(`login:${rlId}`);
400	  await audit(user.id, "user.login");
401	  await createSession(user.id);
402	  // Land where they were HEADING, not on a generic dashboard.
403	  //
404	  // Public CTAs like "Migrate free →" send a logged-out visitor into
405	  // /dashboard/..., which bounces to /login and — until now — discarded what they
406	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
407	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
408	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
409	  //
410	  // `safeNext` only ever returns a path on THIS site (see its definition): an
411	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
412	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
413	  // discarded rather than sanitised.
414	  const next = safeNext(formData.get("next"));
415	  redirect(next ?? roleHome(user.role));
416	}
