169	     protecting. */
170	  await db.orgInvite.upsert({
171	    where: { orgId_email: { orgId, email: invitedEmail } },
172	    create: {
173	      orgId, email: invitedEmail, role: wantRole, invitedById: user.id,
174	      tokenHash: createHash("sha256").update(token).digest("hex"),
175	      expiresAt: new Date(Date.now() + 7 * 86_400_000),
176	    },
177	    update: {
178	      role: wantRole, invitedById: user.id,
179	      tokenHash: createHash("sha256").update(token).digest("hex"),
180	      expiresAt: new Date(Date.now() + 7 * 86_400_000),
