355	/**
356	 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
357	 * Keyed by `membershipId` for the same reason as `updateMemberRole`.
358	 */
359	export async function removeMember(
360	  membershipId: string,
361	): Promise<{ error?: string; ok?: boolean }> {
362	  const user = await requireUser();
363	
364	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
365	  if (!target) return { error: "That person isn't a member of this organization." };
366	
367	  const actor = await actorMembership(target.orgId, user.id);
368	  if (!actor || !canAdministerOrg(actor.role)) {
369	    return { error: "You don't have permission to remove members from this organization." };
370	  }
371	
372	  const org = await db.organization.findUnique({
373	    where: { id: target.orgId },
374	    select: { ownerId: true },
375	  });
376	  if (!org) return { error: "Organization not found." };
377	  if (target.userId === org.ownerId || target.role === "OWNER") {
378	    return { error: "The organization owner can't be removed." };
379	  }
380	
381	  await db.membership.delete({ where: { id: target.id } });
382	  await db.auditLog.create({
383	    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
384	  });
385	  revalidatePath("/dashboard/team");
386	  return { ok: true };
387	}
