389	/**
390	 * Leave an organization. The owner can't leave their own org (they'd have to
391	 * transfer ownership first — a follow-up), everyone else may.
392	 */
393	export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
394	  const user = await requireUser();
395	
396	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
397	  if (!org) return { error: "Organization not found." };
398	  if (org.ownerId === user.id) {
399	    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
400	  }
401	
402	  const membership = await actorMembership(orgId, user.id);
403	  if (!membership) return { error: "You're not a member of this organization." };
404	
405	  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
406	  await db.auditLog.create({
407	    data: { userId: user.id, action: "org.left", detail: orgId },
408	  });
409	  revalidatePath("/dashboard/team");
410	  return { ok: true };
411	}
