413	/** Cancel an outstanding invitation. Gated by the same `canAdministerOrg` that
414	 *  authorises sending one — anyone who may invite may un-invite. The token is
415	 *  not revoked (it cannot be, it is stateless and already sent); `acceptInvite`
416	 *  checks this row and refuses, which is what makes the button mean something. */
417	export async function revokeInvite(orgId: string, email: string): Promise<{ ok?: boolean; error?: string }> {
418	  const user = await requireUser();
419	  await assertNotImpersonating();
420	  /* Same two-step the invite path uses: resolve the caller's membership in THIS
421	     org, then ask whether that role may administer it. `canAdministerOrg` takes
422	     a role, not a user — it is the single definition of the permission and both
423	     paths go through it. */
424	  const actor = await actorMembership(orgId, user.id);
425	  if (!actor || !canAdministerOrg(actor.role)) {
426	    return { error: "You don't have permission to manage invitations for this organization." };
427	  }
428	  const r = await db.orgInvite.updateMany({
429	    where: { orgId, email: email.trim().toLowerCase(), acceptedAt: null, revokedAt: null },
430	    data: { revokedAt: new Date() },
431	  });
432	  if (r.count === 0) return { error: "That invitation has already been accepted or cancelled." };
433	  revalidatePath("/dashboard/team");
434	  return { ok: true };
435	}
