60	test("x-real-ip is preferred — nginx sets it unconditionally from $remote_addr", () => {
61	  const ip = trustedClientIp(
62	    req({ "x-forwarded-for": "203.0.113.77, 51.79.162.96", "x-real-ip": "51.79.162.96" }),
63	  );
64	  assert.equal(ip, "51.79.162.96");
65	});
