67	test("a forged x-real-ip cannot beat the proxy: nginx overwrites, so only one value arrives", () => {
68	  // The caller sends a junk x-real-ip; nginx replaces it. We model the post-nginx
69	  // request. What must NOT happen is a non-IP string becoming a bucket key.
70	  assert.equal(trustedClientIp(req({ "x-real-ip": "not-an-ip" , "x-forwarded-for": "9.9.9.9, 51.79.162.96" })), "51.79.162.96");
71	});
