73	test("no proxy headers at all → the shared UNKNOWN bucket, never a caller value", () => {
74	  assert.equal(trustedClientIp(req({})), UNKNOWN_IP);
75	  assert.equal(trustedClientIp(req({ "x-forwarded-for": "bogus, alsobogus" })), UNKNOWN_IP);
