91	  const opts = { max: 3, windowMs: 60_000 };
92	
93	  // Same real peer, a different forged first hop every time — the attack.
94	  const attempt = (n: number) =>
95	    toolRateLimitByIp(req({ "x-forwarded-for": `10.0.0.${n}, ${peer}` }), tool, opts);
96	
97	  assert.equal(attempt(1), null, "1st allowed");
98	  assert.equal(attempt(2), null, "2nd allowed");
99	  assert.equal(attempt(3), null, "3rd allowed");
100	
101	  const blocked = attempt(4);
102	  assert.ok(blocked, "the 4th must be blocked despite a fresh forged XFF hop");
103	  assert.equal(blocked!.status, 429);
104	  assert.ok(blocked!.headers.get("Retry-After"), "429 must carry Retry-After");
105	});
