107	test("genuinely distinct peers still get their own budget", () => {
108	  const tool = `t-${randomUUID()}`;
109	  const opts = { max: 1, windowMs: 60_000 };
110	  assert.equal(toolRateLimitByIp(req({ "x-real-ip": "198.51.100.1" }), tool, opts), null);
111	  assert.ok(toolRateLimitByIp(req({ "x-real-ip": "198.51.100.1" }), tool, opts), "same peer blocked");
112	  assert.equal(
113	    toolRateLimitByIp(req({ "x-real-ip": "198.51.100.2" }), tool, opts),
