123	/** Every `route.ts` under app/api, as [routePath, source]. */
124	function routeSources(): [string, string][] {
125	  const out: [string, string][] = [];
126	  const walk = (dir: string) => {
127	    for (const entry of readdirSync(dir, { withFileTypes: true })) {
128	      const full = path.join(dir, entry.name);
129	      if (entry.isDirectory()) walk(full);
130	      else if (entry.name === "route.ts") {
131	        out.push([path.relative(API_DIR, full).replaceAll(path.sep, "/"), readFileSync(full, "utf8")]);
132	      }
133	    }
134	  };
135	  walk(API_DIR);
136	  return out;
