/**
 * GET /api/v1/servers
 * Bearer-token authenticated. Returns the caller's servers.
 *
 *   Authorization: Bearer nxe_<prefix>_<random>    (ApiToken)
 *   Authorization: Bearer nxk_live_<random>        (ApiKey — what Settings issues)
 */
export async function GET(req: Request) {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status, headers: NO_STORE_HEADERS });
  }

  // Enforce read scope. Legacy tokens (no scopes recorded) are READ-ONLY — they
  // satisfy this check and nothing that mutates. See `tokenHasScope` in
  // lib/api-auth.ts; a mutating endpoint must use `authorizeApiRequest`.
  if (!tokenHasScope(auth, "servers:read")) {
    return NextResponse.json(
      { error: "Token missing required scope: servers:read" },
      { status: 403, headers: NO_STORE_HEADERS }
    );
  }

  const servers = await db.server.findMany({
    where: { userId: auth.user.id },
    orderBy: { createdAt: "desc" },
    select: {
      id: true,
      name: true,
      status: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },
  });

  // Per-account inventory (names + how to actually reach them). This used to
  // return `ipAddress` — the VM's address on the internal NAT bridge
  // (10.20.0.0/24), unreachable from outside this host — instead of the
  // connection info the dashboard itself shows the customer (same computation
  // as app/dashboard/servers/[id]/page.tsx): the node's public IP + this
  // server's DNAT `sshPort`, or the dedicated IP directly when the server has
  // one. A server with neither yet (still provisioning) reports `host: null`
  // rather than a private address that only looks like an answer.
  //
  // The URL is identical for every token holder, so a shared cache keyed on the
  // URL alone would serve one customer's server list to the next —
  // `Authorization` is a request header and does not vary the cache key on its
  // own. `private` is the control that matters.
  return NextResponse.json(
    {
      servers: servers.map((s) => {
        const dedicated = s.dedicatedIp?.address ?? null;
        const publicIp = s.node?.publicIp ?? process.env.PUBLIC_IP ?? null;
        const host = dedicated ?? publicIp;
        const port = dedicated ? 22 : s.sshPort;
        return {
          id: s.id,
          name: s.name,
          status: s.status,
          host: host && port ? host : null,
          port: host && port ? port : null,
        };
      }),
    },
    { headers: NO_STORE_HEADERS }
  );
}

