import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import {
  extractBearer,
  hashToken,
  tokenHasScope,
  apiKeyScopeToScopes,
  TOKEN_PREFIX,
  API_KEY_PREFIX,
  type ApiAuthResult,
} from "../lib/api-auth.ts";

/**
 * Customer portal P1 #13: a key generated in Settings (`nxk_live_…`, the
 * `ApiKey` model) could never authenticate anything, because `api-auth.ts`
 * only ever recognised `nxe_…` tokens from the DIFFERENT `ApiToken` model.
 * Every key a customer ever generated through the only reachable UI was dead
 * on arrival, silently, forever.
 *
 * `lib/api-auth.ts` is deliberately import-safe (Prisma is loaded lazily
 * inside function bodies specifically so this file can be exercised directly
 * — see its module docblock), so the scope-authorization logic is tested for
 * real here rather than by reasoning about it or grepping source text.
 */

test("both credential prefixes are recognised", () => {
  assert.equal(TOKEN_PREFIX, "nxe");
  assert.equal(API_KEY_PREFIX, "nxk");
});

test("extractBearer is prefix-agnostic — it just reads the header", () => {
  const reqFor = (auth: string | null) =>
    new Request("https://nxeon.cloud/api/v1/servers", {
      headers: auth ? { authorization: auth } : {},
    });
  assert.equal(extractBearer(reqFor("Bearer nxe_ab12_secret")), "nxe_ab12_secret");
  assert.equal(extractBearer(reqFor("Bearer nxk_live_secret")), "nxk_live_secret");
  assert.equal(extractBearer(reqFor("bearer nxk_live_secret")), "nxk_live_secret", "case-insensitive scheme");
  assert.equal(extractBearer(reqFor(null)), null);
  assert.equal(extractBearer(reqFor("Basic dXNlcjpwYXNz")), null, "only Bearer is accepted");
});

test("hashToken is a deterministic sha256 hex digest, never the plaintext", () => {
  const a = hashToken("nxk_live_abc123");
  const b = hashToken("nxk_live_abc123");
  const c = hashToken("nxk_live_abc124");
  assert.equal(a, b, "same input, same hash");
  assert.notEqual(a, c);
  assert.match(a, /^[0-9a-f]{64}$/, "sha256 hex is 64 lowercase hex chars");
  assert.notEqual(a, "nxk_live_abc123", "the digest is never the raw token");
});

// ── ApiKey.scope -> the array shape tokenHasScope actually understands ──────

test("apiKeyScopeToScopes: 'full' is the global wildcard, same as ApiToken's '*'", () => {
  assert.deepEqual(apiKeyScopeToScopes("full"), ["*"]);
});

test("apiKeyScopeToScopes: a specific scope maps to itself, exactly", () => {
  assert.deepEqual(apiKeyScopeToScopes("servers:read"), ["servers:read"]);
  assert.deepEqual(apiKeyScopeToScopes("metrics:read"), ["metrics:read"]);
});

// ── The authorization decision itself, exercised for both credential kinds ──

function authed(scopes: string[]): ApiAuthResult {
  return { ok: true, user: {} as never, tokenId: "t1", scopes };
}

test("an ApiKey created with scope='full' can call any route (translated to the '*' wildcard)", () => {
  const auth = authed(apiKeyScopeToScopes("full"));
  assert.ok(tokenHasScope(auth, "servers:read"));
  assert.ok(tokenHasScope(auth, "servers:delete"), "the whole point of 'full' — it is not scoped to reads");
  assert.ok(tokenHasScope(auth, "metrics:read"));
});

test("an ApiKey created with scope='servers:read' can read servers and nothing else", () => {
  const auth = authed(apiKeyScopeToScopes("servers:read"));
  assert.ok(tokenHasScope(auth, "servers:read"));
  assert.ok(!tokenHasScope(auth, "servers:delete"), "read does not imply write/delete");
  assert.ok(!tokenHasScope(auth, "metrics:read"), "scoped to servers, not metrics");
});

test("an ApiKey created with scope='metrics:read' cannot read servers", () => {
  const auth = authed(apiKeyScopeToScopes("metrics:read"));
  assert.ok(tokenHasScope(auth, "metrics:read"));
  assert.ok(!tokenHasScope(auth, "servers:read"), "the P1 #13 route (GET /api/v1/servers) must refuse this key");
});

// ── Source tripwires: the parts that genuinely need a database to exercise ──

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const API_AUTH = code("../lib/api-auth.ts");
const V1_SERVERS_ROUTE = code("../app/api/v1/servers/route.ts");

test("authenticateApiToken routes nxk_ tokens to the ApiKey path, not the ApiToken 'invalid format' rejection", () => {
  assert.match(
    API_AUTH,
    /raw\.startsWith\(`\$\{API_KEY_PREFIX\}_`\)/,
    "a bearer token starting with nxk_ must be recognised before the nxe_-only format check runs",
  );
  assert.match(API_AUTH, /return authenticateApiKey\(raw\)/);
});

test("the ApiKey path honours revokedAt and suspension the same way the ApiToken path does", () => {
  const fn = /async function authenticateApiKey\([\s\S]*?\n\}/.exec(API_AUTH)?.[0] ?? "";
  assert.ok(fn, "found authenticateApiKey");
  assert.match(fn, /if \(key\.revokedAt\)/, "a revoked key must be refused");
  assert.match(fn, /key\.user\.suspended/, "a suspended account's key must be refused");
  assert.match(fn, /db\.apiKey\s*\n?\s*\.update\(/, "lastUsedAt is stamped, matching the ApiToken path");
});

test("GET /api/v1/servers no longer returns the internal NAT-bridge address", () => {
  // The original bug: `select: { ..., ipAddress: true }` and `ip: s.ipAddress`
  // returned the 10.20.0.0/24 address, which is unreachable from outside the
  // host and useless (or actively misleading) to an API caller.
  assert.ok(
    !/ipAddress:\s*true/.test(V1_SERVERS_ROUTE),
    "must not select the internal ipAddress column",
  );
  assert.ok(!/\bip:\s*s\.ipAddress\b/.test(V1_SERVERS_ROUTE), "must not echo it back either");
  // The replacement: the same host+port computation the dashboard itself uses
  // (app/dashboard/servers/[id]/page.tsx) — the node's public IP + this
  // server's DNAT sshPort, or the dedicated IP when the server has one.
  assert.match(V1_SERVERS_ROUTE, /dedicatedIp:\s*\{\s*select:\s*\{\s*address:\s*true\s*\}\s*\}/);
  assert.match(V1_SERVERS_ROUTE, /node:\s*\{\s*select:\s*\{\s*publicIp:\s*true\s*\}\s*\}/);
  assert.match(V1_SERVERS_ROUTE, /sshPort:\s*true/);
});

test("the two-model authorization contract stays documented, not just implemented", () => {
  // Not a style nitpick: the module docblock is the ONLY place explaining why a
  // second credential model was added rather than migrating Settings onto
  // ApiToken — losing that context is how the next change re-breaks this.
  assert.match(API_AUTH, /ApiToken.*nxe_/s);
  assert.match(API_AUTH, /ApiKey.*nxk_live_/s);
});

