  const auth = authed(apiKeyScopeToScopes("metrics:read"));
  assert.ok(tokenHasScope(auth, "metrics:read"));
  assert.ok(!tokenHasScope(auth, "servers:read"), "the P1 #13 route (GET /api/v1/servers) must refuse this key");
});

