function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const API_AUTH = code("../lib/api-auth.ts");
const V1_SERVERS_ROUTE = code("../app/api/v1/servers/route.ts");

test("authenticateApiToken routes nxk_ tokens to the ApiKey path, not the ApiToken 'invalid format' rejection", () => {
  assert.match(
    API_AUTH,
    /raw\.startsWith\(`\$\{API_KEY_PREFIX\}_`\)/,
    "a bearer token starting with nxk_ must be recognised before the nxe_-only format check runs",
  );
  assert.match(API_AUTH, /return authenticateApiKey\(raw\)/);
});

test("the ApiKey path honours revokedAt and suspension the same way the ApiToken path does", () => {
  const fn = /async function authenticateApiKey\([\s\S]*?\n\}/.exec(API_AUTH)?.[0] ?? "";
  assert.ok(fn, "found authenticateApiKey");
  assert.match(fn, /if \(key\.revokedAt\)/, "a revoked key must be refused");
  assert.match(fn, /key\.user\.suspended/, "a suspended account's key must be refused");
  assert.match(fn, /db\.apiKey\s*\n?\s*\.update\(/, "lastUsedAt is stamped, matching the ApiToken path");
});

test("GET /api/v1/servers no longer returns the internal NAT-bridge address", () => {
  // The original bug: `select: { ..., ipAddress: true }` and `ip: s.ipAddress`
  // returned the 10.20.0.0/24 address, which is unreachable from outside the
  // host and useless (or actively misleading) to an API caller.
  assert.ok(
    !/ipAddress:\s*true/.test(V1_SERVERS_ROUTE),
    "must not select the internal ipAddress column",
  );
  assert.ok(!/\bip:\s*s\.ipAddress\b/.test(V1_SERVERS_ROUTE), "must not echo it back either");
  // The replacement: the same host+port computation the dashboard itself uses
  // (app/dashboard/servers/[id]/page.tsx) — the node's public IP + this
  // server's DNAT sshPort, or the dedicated IP when the server has one.
  assert.match(V1_SERVERS_ROUTE, /dedicatedIp:\s*\{\s*select:\s*\{\s*address:\s*true\s*\}\s*\}/);
  assert.match(V1_SERVERS_ROUTE, /node:\s*\{\s*select:\s*\{\s*publicIp:\s*true\s*\}\s*\}/);
  assert.match(V1_SERVERS_ROUTE, /sshPort:\s*true/);
});

test("the two-model authorization contract stays documented, not just implemented", () => {
  // Not a style nitpick: the module docblock is the ONLY place explaining why a
  // second credential model was added rather than migrating Settings onto
  // ApiToken — losing that context is how the next change re-breaks this.
  assert.match(API_AUTH, /ApiToken.*nxe_/s);
  assert.match(API_AUTH, /ApiKey.*nxk_live_/s);
});

