import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

/**
 * Customer portal P1 #14: nothing ever wrote a `UserSession` row (0 rows in
 * production), so Settings' "Active sessions" list was always empty and its
 * per-device "Revoke" button — which DOES correctly set that row's
 * `revokedAt` (lib/nx/account.ts:revokeSession) — had no row to ever act on.
 * A customer had no real way to kick a stolen device off their account short
 * of the account-wide "sign out everywhere" control.
 *
 * `lib/auth.ts` calls `cookies()`/`headers()` (Next.js request-scoped APIs) at
 * the top of nearly every exported function, so — same as
 * test/auth-lockouts.test.ts's `AUTH` constant — it is read as SOURCE here
 * rather than imported and executed outside a real request. What's asserted
 * is the shape of the fix: every place a session is minted also tracks it,
 * and the one place a session is verified also honours a per-device revoke.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const AUTH = code("../lib/auth.ts");
const ACCOUNT_ACTIONS = code("../lib/actions-account.ts");
const NX_ACCOUNT = code("../lib/nx/account.ts");

// ── Every session-minting path now writes a row ─────────────────────────────

test("createSession tracks the new token as a UserSession row", () => {
  const fn = /export async function createSession\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
  assert.ok(fn, "found createSession");
  assert.match(fn, /await trackSession\(userId, token\)/, "every minted session is recorded");
});

test("trackSession writes userAgent, ip and location, hashes the token, and never throws", () => {
  const fn = /async function trackSession\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
  assert.ok(fn, "found trackSession");
  assert.match(fn, /db\.userSession\.create\(/);
  assert.match(fn, /tokenHash:\s*sessionTokenHash\(token\)/, "never the raw token — same reasoning as ApiKey.keyHash");
  assert.match(fn, /userAgent/);
  assert.match(fn, /\bip\b/);
  assert.match(fn, /location/);
  // Best-effort: a geo/DB hiccup must never be the reason a sign-in fails.
  assert.match(fn, /catch \(e\)/, "wrapped so a failure here cannot break login");
});

test("the session token is hashed with sha256 before it ever reaches the database", () => {
  assert.match(
    AUTH,
    /function sessionTokenHash\(token: string\): string \{\s*return createHash\("sha256"\)\.update\(token\)\.digest\("hex"\);/,
  );
});

test("an unknown IP is stored as null, never the 'unknown' sentinel string", () => {
  const fn = /async function trackSession\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
  assert.match(fn ?? "", /rawIp === UNKNOWN_IP \? null : rawIp/);
});

// ── Per-device revoke actually blocks the next request ──────────────────────

test("realUser refuses a token whose tracked UserSession row is revoked", () => {
  const fn = /export const realUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
  assert.ok(fn, "found realUser");
  assert.match(fn, /db\.userSession\.findUnique\(\{\s*where:\s*\{\s*tokenHash\s*\}/, "looked up by THIS token's own hash");
  assert.match(fn, /if \(tracked\?\.revokedAt\) return null;/, "a revoked row must end the session, not just be display data");
});

test("a token with no tracked row is treated as valid (fail-open for pre-existing sessions)", () => {
  const fn = /export const realUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
  // The revocation check must be conditional on `tracked` existing, not assume
  // every token has a row — deploying this must not mass-log-out every
  // customer who was already signed in before UserSession tracking existed.
  assert.match(fn ?? "", /if \(tracked\) \{/);
  assert.ok(
    !/if \(!tracked\) return null;/.test(fn ?? ""),
    "a MISSING row must never be treated as revoked — that would force-logout every pre-existing session on deploy",
  );
});

test("realUser refreshes lastSeenAt for a live tracked session, but only occasionally", () => {
  const fn = /export const realUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
  assert.match(fn ?? "", /db\.userSession\s*\n?\s*\.update\(\{ where: \{ id: tracked\.id \}, data: \{ lastSeenAt: new Date\(\) \} \}\)/);
  assert.match(fn ?? "", /\.catch\(\(\) => \{\}\);/, "best-effort — must not block the request");
});

// ── "Sign out everywhere else" / password change actually clear tracked rows ─

test("changePassword and signOutOtherSessions revoke every OTHER tracked row, not just sessionVersion", () => {
  assert.match(
    ACCOUNT_ACTIONS,
    /createSession\(user\.id, \{ revokeOtherSessions: true \}\)/g,
    "at least one call site passes the flag",
  );
  const matches = [...ACCOUNT_ACTIONS.matchAll(/createSession\(user\.id, \{ revokeOtherSessions: true \}\)/g)];
  assert.equal(
    matches.length,
    2,
    "both changePassword and signOutOtherSessions must revoke tracked rows, or Settings would still list a device that sessionVersion already logged out",
  );
});

test("createSession honours revokeOtherSessions by revoking tracked rows before minting the new one's row", () => {
  const fn = /export async function createSession\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
  assert.match(fn ?? "", /if \(opts\?\.revokeOtherSessions\) \{/);
  assert.match(fn ?? "", /db\.userSession\s*\n?\s*\.updateMany\(\{ where: \{ userId, revokedAt: null \}, data: \{ revokedAt: new Date\(\) \} \}\)/);
});

// ── The UI action this closes the loop for (lib/nx/account.ts, unchanged but load-bearing) ─

test("revokeSession / revokeOtherSessions already scope their write to the caller's own rows", () => {
  // These were already correct before this fix — the bug was that they had
  // nothing to act on. Locking in that they stay scoped to `user.id`.
  assert.match(NX_ACCOUNT, /db\.userSession\.updateMany\(\{\s*where:\s*\{\s*id,\s*userId:\s*user\.id,\s*revokedAt:\s*null\s*\}/);
  assert.match(
    NX_ACCOUNT,
    /db\.userSession\.updateMany\(\{\s*where:\s*\{\s*userId:\s*user\.id,\s*revokedAt:\s*null,\s*NOT:\s*\{\s*tokenHash:\s*currentTokenHash\s*\}\s*\}/,
  );
});

