import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { canAdministerOrg, INVITE_TTL_HOURS } from "../lib/team-guard.ts";

/**
 * Customer portal P1 #15: the Team UI's own copy claimed "These are the roles
 * the permission system actually enforces", and separately claimed ADMIN
 * manages "servers and services" and BILLING controls "invoices, payment
 * methods and plans" — none of which is true. No Server/Domain/Invoice model
 * has any relationship to Organization anywhere in prisma/schema.prisma (a
 * full-repo grep for `orgId` outside lib/actions-teams.ts, lib/team-guard.ts
 * and the GDPR export turns up nothing else): there is no "team-owned
 * resource" for a role to grant access to. That was a real, deliberate,
 * documented decision (see the docblock at the top of lib/actions-teams.ts),
 * not an oversight — the oversight was the UI copy never being updated to
 * match it, directly contradicting the honest disclaimer already rendered two
 * paragraphs below it on the same panel.
 *
 * What IS real and IS enforced: `canAdministerOrg` gates every mutation that
 * touches org membership itself (invite / re-role / remove / cancel-invite).
 * This file locks that in with the real function (pure, safely importable —
 * lib/team-guard.ts has no "use server" and no DB import), then uses source
 * tripwires for the parts that need a database (the actions) or a browser
 * (the component copy) to fully exercise.
 *
 * Also covers the invite TTL mismatch (copy said "seven days", the real
 * constant is 72 hours) and OrgInvite.acceptedAt never being set.
 */

// ── The real, enforced rule ──────────────────────────────────────────────────

test("canAdministerOrg: only OWNER and ADMIN may administer an organization", () => {
  assert.equal(canAdministerOrg("OWNER"), true);
  assert.equal(canAdministerOrg("ADMIN"), true);
  assert.equal(canAdministerOrg("MEMBER"), false, "a Member must not be able to invite/re-role/remove");
  assert.equal(canAdministerOrg("BILLING"), false, "Billing has no admin rights today — the UI must not claim otherwise");
  assert.equal(canAdministerOrg(""), false);
  assert.equal(canAdministerOrg("owner"), false, "role strings are stored uppercase; no case-folding surprise");
});

test("INVITE_TTL_HOURS is 72 (3 days) — the value every copy string must match", () => {
  assert.equal(INVITE_TTL_HOURS, 72);
});

// ── Source tripwires: every mutation actually calls the real gate ──────────

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const ACTIONS_TEAMS = code("../lib/actions-teams.ts");
const TEAM_VIEW = code("../components/nx/TeamView.tsx");
const TEAM_PAGE = code("../app/dashboard/team/page.tsx");

test("every team-membership mutation actually consults canAdministerOrg before writing", () => {
  for (const name of ["inviteMember", "updateMemberRole", "removeMember", "revokeInvite"]) {
    const fn = new RegExp(`export async function ${name}\\([\\s\\S]*?\\n\\}`).exec(ACTIONS_TEAMS)?.[0] ?? "";
    assert.ok(fn, `found ${name}`);
    assert.match(
      fn,
      /canAdministerOrg\(actor\.role\)/,
      `${name} must gate on the actor's own Membership role, not trust the caller`,
    );
    assert.match(fn, /await requireUser\(\)/, `${name} must require a real session`);
  }
});

test("the actor's membership is loaded from the DB by (orgId, userId) — never trusted from the client", () => {
  assert.match(
    ACTIONS_TEAMS,
    /async function actorMembership\(orgId: string, userId: string\) \{\s*if \(!orgId\) return null;\s*return db\.membership\.findUnique\(\{\s*where:\s*\{\s*orgId_userId:\s*\{\s*orgId,\s*userId\s*\}\s*\},?\s*\}\);/,
  );
});

test("acceptInvite is the only path that creates a Membership for someone else, and requires consent", () => {
  // Consent = the invitee must be signed in as the invited address and click
  // Accept; inviteMember must never create a Membership directly.
  const invite = /export async function inviteMember\([\s\S]*?\n\}/.exec(ACTIONS_TEAMS)?.[0] ?? "";
  assert.ok(!/db\.membership\.create/.test(invite), "inviteMember must not create membership outright");
  const accept = /export async function acceptInvite\([\s\S]*?\n\}/.exec(ACTIONS_TEAMS)?.[0] ?? "";
  assert.match(accept, /claims\.email !== user\.email\.trim\(\)\.toLowerCase\(\)/, "bound to the invited address");
  assert.match(accept, /db\.membership\.create\(/);
});

// ── OrgInvite.acceptedAt actually gets set ──────────────────────────────────

test("acceptInvite marks the OrgInvite row accepted, so it stops showing as pending", () => {
  const accept = /export async function acceptInvite\([\s\S]*?\n\}/.exec(ACTIONS_TEAMS)?.[0] ?? "";
  assert.ok(accept, "found acceptInvite");
  const createIdx = accept.indexOf("db.membership.create(");
  const acceptedIdx = accept.indexOf("acceptedAt: new Date()");
  assert.ok(createIdx > -1 && acceptedIdx > -1, "both the membership create and the acceptedAt write are present");
  assert.ok(createIdx < acceptedIdx, "acceptedAt is set AFTER the membership actually exists");
  assert.match(
    accept,
    /db\.orgInvite\s*\n?\s*\.updateMany\(\{\s*where:\s*\{\s*orgId:\s*org\.id,\s*email:\s*claims\.email,\s*acceptedAt:\s*null\s*\}/,
  );
});

test("app/dashboard/team/page.tsx's pending-invites query would actually stop listing an accepted invite", () => {
  // This is the observable half of the acceptedAt bug: the loader already
  // filters acceptedAt: null (correct), so the fix has to be on the write side
  // (acceptInvite), not here. Locking in the read side stays a real filter.
  assert.match(TEAM_PAGE, /acceptedAt:\s*null,\s*revokedAt:\s*null,\s*expiresAt:\s*\{\s*gt:\s*new Date\(\)\s*\}/);
});

// ── Invite TTL: copy and DB bookkeeping match the real 72h enforcement ──────

test("the OrgInvite.expiresAt bookkeeping row uses the real INVITE_TTL_HOURS, not a stale hardcoded 7 days", () => {
  assert.ok(
    !/Date\.now\(\)\s*\+\s*7\s*\*\s*86_400_000/.test(ACTIONS_TEAMS),
    "the 7-day hardcode must be gone — it overstated the real 72h JWE expiry by 4 days",
  );
  assert.match(
    ACTIONS_TEAMS,
    /const inviteExpiresAt = new Date\(Date\.now\(\) \+ INVITE_TTL_HOURS \* 60 \* 60 \* 1000\);/,
  );
  // Used for both branches of the upsert, not just one.
