// Seeds real accounts + a real org/membership graph directly into the isolated
// nxeon_verify database, so the Playwright script below can drive REAL login
// and team-page interactions against real rows rather than fixtures.
import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const db = new PrismaClient();

async function main() {
  const password = "Verify123!";
  const hash = await bcrypt.hash(password, 12);

  const owner = await db.user.create({
    data: { email: "owner@verify.test", passwordHash: hash, name: "Owner One" },
  });
  const member = await db.user.create({
    data: { email: "member@verify.test", passwordHash: hash, name: "Member Two" },
  });
  const target = await db.user.create({
    data: { email: "target@verify.test", passwordHash: hash, name: "Target Three" },
  });

  const org = await db.organization.create({
    data: {
      name: "Verify Org",
      ownerId: owner.id,
      members: {
        create: [
          { userId: owner.id, role: "OWNER" },
          { userId: member.id, role: "MEMBER" },
          { userId: target.id, role: "MEMBER" },
        ],
      },
    },
    include: { members: true },
  });

  const targetMembership = org.members.find((m) => m.userId === target.id)!;

  console.log(JSON.stringify({
    ownerId: owner.id,
    memberId: member.id,
    targetId: target.id,
    orgId: org.id,
    targetMembershipId: targetMembership.id,
    password,
  }));
}

main().finally(() => db.$disconnect());

