// Real, end-to-end, browser-driven verification of the two security fixes
// that need more than a unit test: UserSession tracking + per-device revoke,
// and team-role enforcement surviving a direct (non-UI) invocation attempt.
// Runs against the isolated `nxeon_verify` Postgres instance and the `next
// dev` server on 127.0.0.1:4177 — never touches production or staging.
import { chromium, type BrowserContext, type Page } from "playwright";
import { PrismaClient } from "@prisma/client";
import { createHash } from "node:crypto";

const BASE = "http://127.0.0.1:4177";
const db = new PrismaClient();

function sha256(s: string) {
  return createHash("sha256").update(s).digest("hex");
}

async function login(ctx: BrowserContext, email: string, password: string): Promise<Page> {
  const page = await ctx.newPage();
  await page.goto(`${BASE}/login`);
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button[type="submit"]');
  await page.waitForURL(/\/dashboard/, { timeout: 15000 });
  return page;
}

function sessionCookieValue(ctx: BrowserContext): Promise<string | undefined> {
  return ctx.cookies().then((cs) => cs.find((c) => c.name === "nxeon_verify_session")?.value);
}

let failures = 0;
function check(label: string, cond: boolean) {
  if (cond) {
    console.log(`  PASS  ${label}`);
  } else {
    console.log(`  FAIL  ${label}`);
    failures++;
  }
}

async function main() {
  const seed = JSON.parse(process.argv[2]);
  const browser = await chromium.launch();

  console.log("\n=== Part A: real login writes a real UserSession row ===");
  const ctxA = await browser.newContext();
  const pageA = await login(ctxA, "member@verify.test", seed.password);
  const tokenA = await sessionCookieValue(ctxA);
  check("device A got a session cookie", !!tokenA);

  const rowsAfterFirstLogin = await db.userSession.findMany({ where: { userId: seed.memberId } });
  check("exactly one UserSession row exists after one real login", rowsAfterFirstLogin.length === 1);
  const rowA = rowsAfterFirstLogin[0];
  check("the row's tokenHash matches THIS browser's real cookie", rowA?.tokenHash === sha256(tokenA!));
  check("a real user-agent was captured", !!rowA?.userAgent && rowA.userAgent.includes("Chrome") || !!rowA?.userAgent);
  console.log(`    userAgent="${rowA?.userAgent}" ip="${rowA?.ip}" location="${rowA?.location}"`);

  console.log("\n=== Part B: a second real login (second device) tracks a second row ===");
  const ctxB = await browser.newContext();
  const pageB = await login(ctxB, "member@verify.test", seed.password);
  const tokenB = await sessionCookieValue(ctxB);
  check("device B got a DIFFERENT session cookie than device A", !!tokenB && tokenB !== tokenA);

  const rowsAfterSecondLogin = await db.userSession.findMany({ where: { userId: seed.memberId } });
  check("now exactly two UserSession rows exist", rowsAfterSecondLogin.length === 2);
  const rowB = rowsAfterSecondLogin.find((r) => r.tokenHash === sha256(tokenB!));
  check("device B's own row exists and is not revoked yet", !!rowB && !rowB.revokedAt);

  console.log("\n=== Part C: Settings lists the OTHER device, not this one, with a working Revoke ===");
  await pageA.goto(`${BASE}/dashboard/settings`);
  await pageA.waitForSelector("text=Active sessions", { timeout: 10000 });
  const rowCountOnPage = await pageA.locator("text=Revoke").count();
  check("device A's settings page shows exactly 1 other session (itself excluded)", rowCountOnPage === 1);

  await pageA.locator("text=Revoke").first().click();
  // RowAction is a client component calling the server action then presumably
  // updating in place — give it a moment, then re-check the DB directly rather
  // than trust the DOM (the DOM is UI, the DB row is the actual security state).
  await pageA.waitForTimeout(1500);

  const rowBAfterRevoke = await db.userSession.findUnique({ where: { id: rowB!.id } });
  check("device B's UserSession row is now revoked in the database", !!rowBAfterRevoke?.revokedAt);
  const rowAAfterRevoke = await db.userSession.findUnique({ where: { id: rowA!.id } });
  check("device A's OWN row was left alone by revoking device B", !rowAAfterRevoke?.revokedAt);

  console.log("\n=== Part D: the revoked device's NEXT request is actually refused ===");
  await pageB.goto(`${BASE}/dashboard`);
  await pageB.waitForLoadState("networkidle");
  const urlAfterRevoke = pageB.url();
  check(
    `device B is redirected away from /dashboard after its session was revoked (got ${urlAfterRevoke})`,
    /\/login/.test(urlAfterRevoke),
  );

