  const pageA = await login(ctxA, "member@verify.test", seed.password);
  const tokenA = await sessionCookieValue(ctxA);
  check("device A got a session cookie", !!tokenA);

  const rowsAfterFirstLogin = await db.userSession.findMany({ where: { userId: seed.memberId } });
  check("exactly one UserSession row exists after one real login", rowsAfterFirstLogin.length === 1);
  const rowA = rowsAfterFirstLogin[0];
  check("the row's tokenHash matches THIS browser's real cookie", rowA?.tokenHash === sha256(tokenA!));
  check("a real user-agent was captured", !!rowA?.userAgent && rowA.userAgent.includes("Chrome") || !!rowA?.userAgent);
  console.log(`    userAgent="${rowA?.userAgent}" ip="${rowA?.ip}" location="${rowA?.location}"`);

  console.log("\n=== Part B: a second real login (second device) tracks a second row ===");
  const ctxB = await browser.newContext();
  const pageB = await login(ctxB, "member@verify.test", seed.password);
  const tokenB = await sessionCookieValue(ctxB);
  check("device B got a DIFFERENT session cookie than device A", !!tokenB && tokenB !== tokenA);

  const rowsAfterSecondLogin = await db.userSession.findMany({ where: { userId: seed.memberId } });
  check("now exactly two UserSession rows exist", rowsAfterSecondLogin.length === 2);
  const rowB = rowsAfterSecondLogin.find((r) => r.tokenHash === sha256(tokenB!));
  check("device B's own row exists and is not revoked yet", !!rowB && !rowB.revokedAt);

  console.log("\n=== Part C: Settings lists the OTHER device, not this one, with a working Revoke ===");
  await pageA.goto(`${BASE}/dashboard/settings`);
