  const page = await ctx.newPage();
  page.on("dialog", (d) => d.accept());
  await page.goto(`${BASE}/login`);
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button:has-text("Sign in")');
  await page.waitForURL(/\/dashboard/, { timeout: 15000 });
  return page;
}

input.new_string:
async function login(ctx: BrowserContext, email: string, password: string): Promise<Page> {
  const page = await ctx.newPage();
  page.on("dialog", (d) => d.accept());
  await page.goto(`${BASE}/login`, { timeout: 60000 });
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button:has-text("Sign in")');
  try {
    // Generous — this is a `next dev` cold compile of a large server action
    // (lib/actions.ts), not steady-state latency. Real steady-state timing is
    // not what this script is measuring.
    await page.waitForURL(/\/dashboard/, { timeout: 90000 });
  } catch (e) {
    console.error(`    login(${email}) did not reach /dashboard. Current URL: ${page.url()}`);
    console.error(`    page text (first 500 chars): ${(await page.textContent("body"))?.slice(0, 500)}`);
    throw e;
  }
  return page;
}

