import { chromium } from "playwright";

const BASE = "http://127.0.0.1:4177";

async function main() {
  const seed = JSON.parse(process.argv[2]);
  const browser = await chromium.launch();
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  page.on("dialog", (d) => d.accept());
  page.on("console", (msg) => console.log(`  [console.${msg.type()}] ${msg.text()}`));
  page.on("pageerror", (err) => console.log(`  [pageerror] ${err.message}`));

  console.log("goto /login");
  await page.goto(`${BASE}/login`, { timeout: 60000 });
  await page.fill('input[name="email"]', "owner@verify.test");
  await page.fill('input[name="password"]', seed.password);
  await page.click('button:has-text("Sign in")');
  await page.waitForURL(/\/dashboard/, { timeout: 90000 });
  console.log("logged in, now at", page.url());

  console.log("goto /dashboard/settings");
  const resp = await page.goto(`${BASE}/dashboard/settings`, { waitUntil: "domcontentloaded", timeout: 60000 });
  console.log("response status:", resp?.status());
  await page.waitForTimeout(3000);
  const bodyText = await page.textContent("body");
  console.log("body text length:", bodyText?.length);
  console.log("contains 'Active sessions'?", bodyText?.includes("Active sessions"));
  console.log("contains 'Revoke'?", bodyText?.includes("Revoke"));
  console.log("first 800 chars of body text:", bodyText?.slice(0, 800));
  await page.screenshot({ path: "/tank/dev-worktrees/portal-security-fixes/.verify-scratch/settings.png", fullPage: true });
  console.log("screenshot saved");

  await browser.close();
}

main().catch((e) => {
  console.error("diag crashed:", e);
  process.exit(1);
});

