/**
 * The "7-day free trial" promo popup (components/marketing/PromoTrialPopup.tsx)
 * renders a full-viewport `.promo-scrim` dialog for a new-looking account and
 * intercepts ALL pointer events until dismissed — this is what silently
 * swallowed the very first Revoke/Remove click attempts in this script (the
 * click landed on the scrim, not the button underneath, and Playwright's
 * auto-retry-on-interception eventually timed out rather than erroring
 * immediately, which is why it looked like nothing happened rather than
 * failing loudly). Idempotent no-op when the popup isn't showing.
 */
async function closePromoIfPresent(page: Page): Promise<void> {
  const closeBtn = page.locator('button.promo-modal-close, [aria-label="Close"]');
  if (await closeBtn.count()) {
    try {
      await closeBtn.first().click({ timeout: 3000 });
      console.log("    (dismissed the promo popup that was blocking clicks)");
    } catch {
      /* already gone, or a different overlay — the caller's own click will surface any real issue */
    }
  }
}

