import { PrismaClient } from "@prisma/client";
import { createHash, randomBytes } from "node:crypto";

const db = new PrismaClient();

async function main() {
  // Real user with a real Server + Node + sshPort, matching production shape.
  const user = await db.user.create({
    data: { email: "apiuser@verify.test", passwordHash: "x", name: "API User", heardAboutUs: "skipped" },
  });
  const node = await db.node.create({
    data: { name: "verify-node", publicIp: "203.0.113.50", provider: "OVH", apiUrl: "https://x", tokenId: "x", tokenSecret: "x" },
  });
  const server = await db.server.create({
    data: {
      userId: user.id, name: "test-vps", hostname: `test-vps-${Date.now()}`,
      status: "RUNNING", nodeId: node.id, sshPort: 20123, ipAddress: "10.20.0.42",
    },
  });

  // Exactly what createApiKey (lib/nx/account.ts) does.
  const secret = randomBytes(32).toString("base64url");
  const key = `nxk_live_${secret}`;
  await db.apiKey.create({
    data: {
      userId: user.id, name: "verify-key", scope: "full",
      keyHash: createHash("sha256").update(key).digest("hex"),
      prefix: key.slice(0, 13),
    },
  });

  console.log(JSON.stringify({ key, userId: user.id, serverId: server.id, nodeId: node.id }));
}
main().finally(() => db.$disconnect());
EOF
